PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,source_url TEXT NOT NULL UNIQUE,platform TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',creator TEXT NOT NULL DEFAULT '',game TEXT NOT NULL DEFAULT '',discovered_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_permissions(source_id TEXT PRIMARY KEY REFERENCES sources(id) ON DELETE RESTRICT,status TEXT NOT NULL DEFAULT 'UNKNOWN',license_type TEXT NOT NULL DEFAULT '',permission_evidence TEXT NOT NULL DEFAULT '',editing_allowed INTEGER NOT NULL DEFAULT 0,commercial_use_allowed INTEGER NOT NULL DEFAULT 0,reviewed_by_owner INTEGER NOT NULL DEFAULT 0,attribution TEXT NOT NULL DEFAULT '',expires_at TEXT,notes TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media_assets(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE RESTRICT,original_path TEXT NOT NULL,file_name TEXT NOT NULL,file_size INTEGER NOT NULL,sha256 TEXT NOT NULL,probe_json TEXT,state TEXT NOT NULL DEFAULT 'IMPORTED',created_at TEXT NOT NULL,UNIQUE(source_id,sha256));
CREATE TABLE IF NOT EXISTS candidate_moments(id TEXT PRIMARY KEY,media_id TEXT NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT,start_seconds REAL NOT NULL,end_seconds REAL NOT NULL,detector TEXT NOT NULL,score REAL,explanation TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'NEEDS_REVIEW',created_at TEXT NOT NULL,UNIQUE(media_id,start_seconds,end_seconds,detector));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,job_type TEXT NOT NULL,status TEXT NOT NULL,source_id TEXT REFERENCES sources(id),media_id TEXT REFERENCES media_assets(id),payload_json TEXT NOT NULL DEFAULT '{}',attempt_count INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 3,error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,started_at TEXT,finished_at TEXT);
CREATE INDEX IF NOT EXISTS idx_jobs_status_created ON jobs(status,created_at);
CREATE TABLE IF NOT EXISTS published_videos(id TEXT PRIMARY KEY,source_id TEXT REFERENCES sources(id),media_id TEXT REFERENCES media_assets(id),candidate_id TEXT REFERENCES candidate_moments(id),output_path TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',template_id TEXT NOT NULL DEFAULT '',qc_status TEXT NOT NULL DEFAULT 'PENDING',publishing_status TEXT NOT NULL DEFAULT 'NOT_CONFIGURED',youtube_video_id TEXT UNIQUE,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS analytics_snapshots(id TEXT PRIMARY KEY,published_video_id TEXT NOT NULL REFERENCES published_videos(id),captured_at TEXT NOT NULL,metrics_json TEXT NOT NULL,provider TEXT NOT NULL DEFAULT 'youtube_analytics_api');
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS system_events(id TEXT PRIMARY KEY,level TEXT NOT NULL,event_type TEXT NOT NULL,message TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
